"""BFF secrets routes — read & edit with curated shape.

Curated wrapper over services/cowork_agent/agent_env via the
SecretsScope handle in services.cowork_agent.scopes. Five routes:

  GET    /api/secrets                  list with masked previews
  GET    /api/secrets/{key}/reveal     raw value for one key
  PUT    /api/secrets                  bulk replace
  PATCH  /api/secrets/{key}            single set/update
  DELETE /api/secrets/{key}            single hard-delete (idempotent)

See docs/bff-endpoints-design.md §9.2 for the full contract.
"""

from __future__ import annotations

import logging
from typing import Optional

from fastapi import APIRouter, HTTPException
from pydantic import BaseModel

from routers.cowork_agent.bff.filters import (
    HIDDEN_KEYS,
    is_valid_key,
    is_valid_value,
    preview_value,
)
from services.cowork_agent import scopes

logger = logging.getLogger(__name__)

router = APIRouter()


# ── Pydantic models ───────────────────────────────────────────────────────────


class SecretSummary(BaseModel):
    key: str
    is_set: bool
    preview: Optional[str] = None


class ListSecretsResponse(BaseModel):
    items: list[SecretSummary]
    total: int


class RevealResponse(BaseModel):
    key: str
    value: str


class SecretItem(BaseModel):
    key: str
    value: str


class PutSecretsRequest(BaseModel):
    items: list[SecretItem]


class PatchSecretRequest(BaseModel):
    value: str


class DeleteSecretResponse(BaseModel):
    key: str
    deleted: bool


# ── Helpers ───────────────────────────────────────────────────────────────────


def _shape(entries: list[dict]) -> list[SecretSummary]:
    """Filter on the way out (P4): drop hidden keys, drop malformed
    keys (log WARN), and convert to typed summaries."""
    out: list[SecretSummary] = []
    for e in entries:
        key = (e.get("key") or "").strip()
        if not key:
            continue
        if not is_valid_key(key):
            logger.warning("Skipping malformed key in secrets store: %r", key)
            continue
        if key in HIDDEN_KEYS:
            continue
        value = e.get("value") or ""
        if not is_valid_value(value):
            # Lenient-on-read: surface as is_set=false rather than rejecting.
            out.append(SecretSummary(key=key, is_set=False, preview=None))
            continue
        is_set = bool(value.strip())
        out.append(
            SecretSummary(
                key=key,
                is_set=is_set,
                preview=preview_value(value) if is_set else None,
            )
        )
    out.sort(key=lambda s: s.key)
    return out


def _bad_request(code: str, message: str) -> HTTPException:
    return HTTPException(status_code=400, detail={"code": code, "message": message})


def _not_found() -> HTTPException:
    return HTTPException(
        status_code=404,
        detail={"code": "key_not_found", "message": "Secret not found."},
    )


def _scope_unavailable() -> HTTPException:
    return HTTPException(
        status_code=500,
        detail={
            "code": "scope_unavailable",
            "message": "Secrets store is not accessible.",
        },
    )


def _require_valid_key(key: str) -> None:
    if not is_valid_key(key):
        raise _bad_request("invalid_key", "Key must match ^[A-Z_][A-Z0-9_]*$.")


def _require_valid_value(value: str) -> None:
    if not is_valid_value(value):
        raise _bad_request(
            "invalid_value", "Value must not contain newline or null bytes."
        )


def _require_writable_key(key: str) -> None:
    _require_valid_key(key)
    if key in HIDDEN_KEYS:
        raise _bad_request("invalid_key", "Key is reserved and cannot be modified.")


# ── Routes ────────────────────────────────────────────────────────────────────


@router.get("/api/secrets", response_model=ListSecretsResponse)
def list_secrets() -> ListSecretsResponse:
    handle = scopes.resolve_scope("secrets")
    try:
        entries = handle.load()
    except OSError as exc:
        raise _scope_unavailable() from exc
    items = _shape(entries)
    return ListSecretsResponse(items=items, total=len(items))


@router.get("/api/secrets/{key}/reveal", response_model=RevealResponse)
def reveal_secret(key: str) -> RevealResponse:
    _require_valid_key(key)
    if key in HIDDEN_KEYS:
        raise _not_found()
    handle = scopes.resolve_scope("secrets")
    try:
        entries = handle.load()
    except OSError as exc:
        raise _scope_unavailable() from exc
    entry = next((e for e in entries if e.get("key") == key), None)
    if entry is None:
        raise _not_found()
    return RevealResponse(key=key, value=entry.get("value") or "")


@router.put("/api/secrets", response_model=ListSecretsResponse)
def put_secrets(body: PutSecretsRequest) -> ListSecretsResponse:
    seen: set[str] = set()
    cleaned: list[dict] = []
    for item in body.items:
        key = item.key.strip()
        _require_writable_key(key)
        _require_valid_value(item.value)
        if key in seen:
            raise _bad_request("duplicate_key", f"Duplicate key in items: {key}")
        seen.add(key)
        cleaned.append({"key": key, "value": item.value})

    handle = scopes.resolve_scope("secrets")
    try:
        handle.save(cleaned)
        entries = handle.load()
    except OSError as exc:
        raise _scope_unavailable() from exc
    items = _shape(entries)
    return ListSecretsResponse(items=items, total=len(items))


@router.patch("/api/secrets/{key}", response_model=SecretSummary)
def patch_secret(key: str, body: PatchSecretRequest) -> SecretSummary:
    _require_writable_key(key)
    _require_valid_value(body.value)
    handle = scopes.resolve_scope("secrets")
    try:
        handle.upsert(key, body.value)
    except OSError as exc:
        raise _scope_unavailable() from exc
    is_set = bool(body.value.strip())
    return SecretSummary(
        key=key,
        is_set=is_set,
        preview=preview_value(body.value) if is_set else None,
    )


@router.delete("/api/secrets/{key}", response_model=DeleteSecretResponse)
def delete_secret(key: str) -> DeleteSecretResponse:
    _require_valid_key(key)
    if key in HIDDEN_KEYS:
        return DeleteSecretResponse(key=key, deleted=False)
    handle = scopes.resolve_scope("secrets")
    try:
        deleted = handle.delete(key)
    except OSError as exc:
        raise _scope_unavailable() from exc
    return DeleteSecretResponse(key=key, deleted=deleted)

"""
REST routes for the Manus AI connector (API key approach).

Endpoints:
  POST /api/connectors/manus/token       — receive & validate an API key
  GET  /api/connectors/manus/status      — current connection status
  POST /api/connectors/manus/disconnect   — delete stored key
  POST /api/connectors/manus/reconnect    — re-validate stored key
"""

import logging

from fastapi import APIRouter, HTTPException
from fastapi.responses import JSONResponse
from pydantic import BaseModel

from services.cowork_agent.connectors.manus_connector import (
    delete_manus_key,
    get_manus_key,
    get_status,
    save_manus_key,
    validate_key,
)

log = logging.getLogger(__name__)
router = APIRouter()


class TokenBody(BaseModel):
    token: str


@router.post("/api/connectors/manus/token")
async def submit_manus_key(body: TokenBody) -> JSONResponse:
    """Validate a Manus API key, store it, and return the connection status."""
    api_key = body.token.strip()
    if not api_key:
        raise HTTPException(400, detail="API key cannot be empty.")

    result = await validate_key(api_key)

    if result.get("valid"):
        save_manus_key(api_key)
        log.info("Manus connected")
        return JSONResponse({"status": "connected"})
    else:
        return JSONResponse(
            {"status": result["status"], "error": result.get("error", "Validation failed.")},
            status_code=400 if result["status"] == "needs_auth" else 502,
        )


@router.get("/api/connectors/manus/status")
async def manus_status() -> JSONResponse:
    """Return the current Manus connector status."""
    status = await get_status()
    return JSONResponse(status)


@router.post("/api/connectors/manus/disconnect")
async def disconnect_manus() -> JSONResponse:
    delete_manus_key()
    return JSONResponse({"status": "needs_auth"})


@router.post("/api/connectors/manus/reconnect")
async def reconnect_manus() -> JSONResponse:
    api_key = get_manus_key()
    if not api_key:
        return JSONResponse({"status": "needs_auth", "error": "No API key stored."})

    result = await validate_key(api_key)
    if result.get("valid"):
        return JSONResponse({"status": "connected"})
    else:
        return JSONResponse(
            {"status": result["status"], "error": result.get("error", "")},
            status_code=502,
        )

"""
REST routes for the Google Drive connector.

Exposes:
  GET  /api/connectors/gdrive/remotes
  POST /api/connectors/gdrive/remotes
  GET  /api/connectors/gdrive/sessions/{session_id}
  DELETE /api/connectors/gdrive/remotes/{name}
  POST /api/connectors/gdrive/sessions/{session_id}/cancel
"""

import logging

from fastapi import APIRouter, HTTPException, Request
from fastapi.responses import JSONResponse, Response
from pydantic import BaseModel

from services.cowork_agent.connectors.gdrive_rclone import (
    cancel_session,
    create_remote_session,
    delete_remote,
    delete_remote_folder,
    get_session,
    list_drive_remotes,
    list_remote_folders,
    mkdir_remote_path,
    rclone_available,
    upload_file_to_remote,
    validate_remote_name,
)

log = logging.getLogger(__name__)
router = APIRouter()

# v1 cap: large enough for ordinary docs/images, conservative enough that the
# Coder edge proxy and Next.js dev rewrite stay reliable.
MAX_UPLOAD_BYTES = 500 * 1024 * 1024  # 500 MiB


# ---------------------------------------------------------------------------
# GET /api/connectors/gdrive/remotes
# ---------------------------------------------------------------------------

@router.get("/api/connectors/gdrive/remotes")
async def get_gdrive_remotes() -> JSONResponse:
    if not await rclone_available():
        raise HTTPException(
            503,
            detail="Could not reach rclone daemon. Check that rclone is installed and running.",
        )
    remotes = await list_drive_remotes()
    return JSONResponse({"remotes": remotes})


# ---------------------------------------------------------------------------
# POST /api/connectors/gdrive/remotes
# ---------------------------------------------------------------------------

class CreateRemoteBody(BaseModel):
    name: str
    force: bool = False


@router.post("/api/connectors/gdrive/remotes")
async def create_gdrive_remote(body: CreateRemoteBody) -> JSONResponse:
    if not await rclone_available():
        raise HTTPException(503, detail="Could not reach rclone daemon.")

    # Validate name
    err = await validate_remote_name(body.name)
    if err:
        raise HTTPException(400, detail=err)

    try:
        session = await create_remote_session(body.name, force=body.force)
    except RuntimeError as exc:
        # Concurrent flow
        raise HTTPException(409, detail=str(exc)) from exc

    return JSONResponse(
        {"session_id": session.session_id, "status": "pending"},
        status_code=202,
    )


# ---------------------------------------------------------------------------
# GET /api/connectors/gdrive/sessions/{session_id}
# ---------------------------------------------------------------------------

@router.get("/api/connectors/gdrive/sessions/{session_id}")
async def poll_gdrive_session(session_id: str) -> JSONResponse:
    session = get_session(session_id)
    if not session:
        raise HTTPException(404, detail="Session not found or expired.")

    payload: dict = {"status": session.status}
    if session.status == "awaiting_oauth" and session.auth_url:
        payload["auth_url"] = session.auth_url
        payload["needs_manual_code"] = session.needs_manual_code
    if session.status == "completed":
        payload["remote_name"] = session.remote_name
    if session.status == "failed" and session.error:
        payload["error"] = session.error

    return JSONResponse(payload)


# ---------------------------------------------------------------------------
# DELETE /api/connectors/gdrive/remotes/{name}
# ---------------------------------------------------------------------------

@router.delete("/api/connectors/gdrive/remotes/{name}")
async def remove_gdrive_remote(name: str) -> Response:
    if not await rclone_available():
        raise HTTPException(503, detail="Could not reach rclone daemon.")
    try:
        await delete_remote(name)
    except Exception as exc:
        raise HTTPException(500, detail=str(exc)) from exc
    return Response(status_code=204)


# ---------------------------------------------------------------------------
# POST /api/connectors/gdrive/sessions/{session_id}/cancel
# ---------------------------------------------------------------------------

@router.post("/api/connectors/gdrive/sessions/{session_id}/cancel")
async def cancel_gdrive_session(session_id: str) -> JSONResponse:
    await cancel_session(session_id)
    return JSONResponse({"ok": True})


# ---------------------------------------------------------------------------
# POST /api/connectors/gdrive/sessions/{session_id}/submit
# Body: {"code": "<paste from URL bar>"}
# ---------------------------------------------------------------------------

class SubmitCodeBody(BaseModel):
    code: str


@router.post("/api/connectors/gdrive/sessions/{session_id}/submit")
async def submit_gdrive_code(session_id: str, body: SubmitCodeBody) -> JSONResponse:
    """Receive the redirect URL / verification code the user pasted from the browser."""
    session = get_session(session_id)
    if not session:
        raise HTTPException(404, detail="Session not found or expired.")
    if session.status != "awaiting_oauth":
        raise HTTPException(400, detail="Session is not waiting for a verification code.")

    # Accept either the full redirect URL or just the bare code
    code = body.code.strip()
    import re
    m = re.search(r"[?&]code=([^&]+)", code)
    if m:
        code = m.group(1)

    session.verification_input = code
    return JSONResponse({"ok": True})


# ---------------------------------------------------------------------------
# POST /api/connectors/gdrive/remotes/{name}/mkdir
# Body: {"path": "<folder path on remote>"}
# ---------------------------------------------------------------------------

class MkdirBody(BaseModel):
    path: str


@router.post("/api/connectors/gdrive/remotes/{name}/mkdir")
async def mkdir_gdrive_remote(name: str, body: MkdirBody) -> JSONResponse:
    if not await rclone_available():
        raise HTTPException(503, detail="Could not reach rclone.")

    remotes = await list_drive_remotes()
    if not any(r.get("name") == name for r in remotes):
        raise HTTPException(404, detail=f"Remote '{name}' not found.")

    try:
        await mkdir_remote_path(name, body.path)
    except ValueError as exc:
        raise HTTPException(400, detail=str(exc)) from exc
    except RuntimeError as exc:
        raise HTTPException(400, detail=str(exc)) from exc

    return JSONResponse({"ok": True, "path": body.path})


# ---------------------------------------------------------------------------
# GET /api/connectors/gdrive/remotes/{name}/folders
# Lists top-level folders visible to rclone on the remote.
# ---------------------------------------------------------------------------

@router.get("/api/connectors/gdrive/remotes/{name}/folders")
async def list_gdrive_remote_folders(name: str) -> JSONResponse:
    if not await rclone_available():
        raise HTTPException(503, detail="Could not reach rclone.")

    remotes = await list_drive_remotes()
    if not any(r.get("name") == name for r in remotes):
        raise HTTPException(404, detail=f"Remote '{name}' not found.")

    try:
        folders = await list_remote_folders(name)
    except RuntimeError as exc:
        raise HTTPException(400, detail=str(exc)) from exc

    return JSONResponse({"folders": folders})


# ---------------------------------------------------------------------------
# POST /api/connectors/gdrive/remotes/{name}/rmdir
# Body: {"path": "<folder path>"} — purges folder + rclone-visible contents.
# ---------------------------------------------------------------------------

class RmdirBody(BaseModel):
    path: str


@router.post("/api/connectors/gdrive/remotes/{name}/rmdir")
async def rmdir_gdrive_remote(name: str, body: RmdirBody) -> JSONResponse:
    if not await rclone_available():
        raise HTTPException(503, detail="Could not reach rclone.")

    remotes = await list_drive_remotes()
    if not any(r.get("name") == name for r in remotes):
        raise HTTPException(404, detail=f"Remote '{name}' not found.")

    try:
        await delete_remote_folder(name, body.path)
    except ValueError as exc:
        raise HTTPException(400, detail=str(exc)) from exc
    except RuntimeError as exc:
        raise HTTPException(400, detail=str(exc)) from exc

    return JSONResponse({"ok": True, "path": body.path})


# ---------------------------------------------------------------------------
# POST /api/connectors/gdrive/remotes/{name}/upload?path=<folder>&filename=<f>
# Body is the raw file bytes (Content-Type: application/octet-stream).
# Streams to `rclone rcat` stdin — no disk spool, no RAM buffer.
# ---------------------------------------------------------------------------

@router.post("/api/connectors/gdrive/remotes/{name}/upload")
async def upload_to_gdrive_remote(
    name: str,
    request: Request,
    path: str = "",
    filename: str = "",
) -> JSONResponse:
    if not await rclone_available():
        raise HTTPException(503, detail="Could not reach rclone.")

    remotes = await list_drive_remotes()
    if not any(r.get("name") == name for r in remotes):
        raise HTTPException(404, detail=f"Remote '{name}' not found.")

    size_hdr = request.headers.get("content-length")
    size: int | None = None
    if size_hdr and size_hdr.isdigit():
        size = int(size_hdr)
        if size > MAX_UPLOAD_BYTES:
            raise HTTPException(
                413,
                detail=f"File exceeds the {MAX_UPLOAD_BYTES // (1024 * 1024)} MiB cap.",
            )

    try:
        final_path = await upload_file_to_remote(
            name, path, filename, size, request.stream(),
        )
    except ValueError as exc:
        raise HTTPException(400, detail=str(exc)) from exc
    except RuntimeError as exc:
        raise HTTPException(502, detail=f"rclone upload failed: {exc}") from exc

    return JSONResponse({"ok": True, "path": final_path, "size": size})

"""
